values(17,'listening','IELTS Listening Test 188','published',$json${"version":"listening-test-188-v1","test_code":"TEST-188","audio_url":"https://ia903200.us.archive.org/16/items/test-188-converted/TEST_188_Converted.mp3","total_questions":40,"audio_once":true,"sections":[{"number":1,"label":"SECTION 1","range":"Questions 1–10","blocks":[{"kind":"mcq","range":"Questions 1–8","instruction":"Choose the correct answer, A, B or C.","title":"Winsham Farm Visitor Centre","questions":[{"q":1,"text":"The centre has enough accommodation for","options":{"A":"18 people.","B":"20 people.","C":"38 people."}},{"q":2,"text":"The meeting room is currently","options":{"A":"unavailable.","B":"flooded.","C":"booked."}},{"q":3,"text":"Visitors must tell the centre in advance if they want to","options":{"A":"use the centre's kitchen.","B":"have meals cooked for them.","C":"eat at restaurants outside."}},{"q":4,"text":"All visitors on the farm can","options":{"A":"get information about organic farming.","B":"help to feed the animals.","C":"watch a tractor demonstration."}},{"q":5,"text":"On the survival course people have to","options":{"A":"learn to use a map.","B":"find their own food.","C":"run through woodland."}},{"q":6,"text":"From the centre it is easy to walk to","options":{"A":"Exmoor National Park.","B":"the beach.","C":"a cycling route."}},{"q":7,"text":"If the weather is bad visitors can go to a","options":{"A":"cinema.","B":"theatre.","C":"museum."}},{"q":8,"text":"Groups who wish to stay at the centre must pay","options":{"A":"part of the cost in advance.","B":"all the cost in advance.","C":"all of the cost on arrival."}}]},{"kind":"notes","range":"Questions 9–10","instruction":"Complete the notes below.","word_limit":"Write ONE WORD AND/OR A NUMBER for each answer.","title":"Winsham Farm · Address","items":[["Winsham Farm"],[{"q":9}," Road"],["Near Sherborne"],["Postcode: ",{"q":10}]]}]},{"number":2,"label":"SECTION 2","range":"Questions 11–20","blocks":[{"kind":"table","r